// EDIT THIS NODE, then run the workflow manually. Never paste API keys here (they go in n8n credentials).
return [{ json: {
  // CJ product IDs: the long number after "-p-" at the end of a CJ product page URL (keep the quotes).
  pids: ['PASTE-CJ-PRODUCT-ID-HERE'],
  // Store category slug for the product type. One of: home-living, beauty-self-care,
  // fashion-accessories, gifts, desk-stationery, tea-drinkware, travel-accessories, everyday-finds
  type_category: 'desk-stationery',
  // REAL country of origin of the item, e.g. 'China'. Leave '' if you do not know:
  // the draft is then flagged "origin needed" and no origin category is set.
  // Only use 'Japan' if the supplier documents that the item is made in Japan.
  origin_country: '',
  // true = the item is only inspired by Japanese design (adds the "Japanese-inspired" tag).
  japanese_inspired: false,
  // Pricing inputs. usd_to_inr MUST be filled in; shipping comes from CJ unless you type shipping_inr.
  // Shipping lookup: warehouse country code CJ ships from (CN = China, or an EU warehouse code) and the destination.
  ship_from: 'CN',
  ship_to: 'IN',
  usd_to_inr: 0,      // today's exchange rate, update before each run
  shipping_inr: 0,    // leave 0 to use the cheapest CJ shipping line found by the lookup, or type your own cost in INR
  returns_inr: 20,    // allowance for returns and other costs, in INR
  payment_fee: 0.03,  // payment gateway fee as a share of the price
  ad_cost: 0.10,      // ad cost as a share of the price
  margin: 0.25        // target margin as a share of the price
} }];

const s = $('Settings').first().json;
const token = $input.first().json && $input.first().json.data && $input.first().json.data.accessToken;
if (!token) throw new Error('CJ did not return an access token. Check the CJ API key credential. Response: ' + JSON.stringify($input.first().json).slice(0, 300));
const pids = (s.pids || []).map((p) => String(p).trim()).filter((p) => p && !/^PASTE-/i.test(p));
if (!pids.length) throw new Error('Add at least one CJ product ID in the Settings node.');
return pids.map((pid) => ({ json: { pid, token } }));

const s = $('Settings').first().json;
const pid = $('Prepare Products').item.json.pid;
const res = $('Get CJ Product').item.json || {};
const ship = $input.item.json || {};
const p = res.data;
if (!p || typeof p !== 'object') throw new Error(`CJ returned no product for ${pid}: ${res.message || JSON.stringify(res).slice(0, 200)}`);

const TYPE_IDS = { 'home-living': 27, 'beauty-self-care': 28, 'fashion-accessories': 29, 'gifts': 30, 'desk-stationery': 31, 'tea-drinkware': 32, 'travel-accessories': 33, 'everyday-finds': 34 };
const ORIGIN_IDS = { china: 24, japan: 22, korea: 23, taiwan: 25, 'southeast asia': 26 };
const JAPANESE_INSPIRED_TAG_ID = 52;
const typeId = TYPE_IDS[s.type_category];
if (!typeId) throw new Error(`Unknown type_category "${s.type_category}". Use one of: ${Object.keys(TYPE_IDS).join(', ')}`);
if (!Number(s.usd_to_inr) || Number(s.usd_to_inr) <= 0) throw new Error('Set usd_to_inr (today\'s exchange rate) in the Settings node.');
const load = Number(s.payment_fee) + Number(s.ad_cost) + Number(s.margin);
if (!(load >= 0 && load < 0.9)) throw new Error('payment_fee + ad_cost + margin must be below 0.9.');

const clean = (v) => String(v == null ? '' : v)
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/[　-鿿＀-￯]/g, '')
  .replace(/\s+/g, ' ').trim();
const num = (v) => { const m = String(v == null ? '' : v).match(/\d+(\.\d+)?/); return m ? Number(m[0]) : NaN; };

const name = clean(p.productNameEn || p.productName);
const description = clean(p.description).slice(0, 2500);

// Licensed characters and brands must not be sold without a licence.
const LICENSED = /sanrio|hello\s*kitty|san-?x|rilakkuma|my\s*melody|kuromi|cinnamoroll|pompompurin|pochacco|little\s*twin\s*stars|sumikko|chiikawa|miffy|disney|pok[eé]mon|pikachu|nintendo|mario|ghibli|totoro|doraemon|sailor\s*moon|snoopy|peanuts|marvel|bt21|line\s*friends|hermes|louis\s*vuitton|gucci|chanel|nike|adidas/i;
const licensedHit = (name + ' ' + description).match(LICENSED);

// Cost: the highest variant price, so a dearer variant is never sold at a loss.
const variants = Array.isArray(p.variants) ? p.variants : [];
const vCosts = variants.map((v) => num(v.variantSellPrice)).filter((n) => !isNaN(n));
const baseCost = num(p.sellPrice);
const costUsd = vCosts.length ? Math.max(...vCosts) : baseCost;
if (isNaN(costUsd)) throw new Error(`No usable cost for CJ product ${pid}.`);

// Shipping: use the number typed in Settings, else the cheapest CJ line to the destination.
let shipOptions = [];
const sd = ship && ship.data;
if (Array.isArray(sd)) {
  shipOptions = sd.map((o) => ({ name: String(o.logisticName || o.logisticNameEn || '?'), usd: Number(o.logisticPrice), days: String(o.logisticAging || '?') }))
    .filter((o) => !isNaN(o.usd) && o.usd >= 0)
    .sort((a, b) => a.usd - b.usd);
}
let shippingInr = Number(s.shipping_inr) || 0;
let shippingNote = '';
if (!shippingInr && shipOptions.length) {
  const pick = shipOptions[0];
  shippingInr = Math.ceil(pick.usd * Number(s.usd_to_inr));
  shippingNote = `shipping taken from CJ: ${pick.name}, USD ${pick.usd}, ${pick.days} days (cheapest line; check it has tracking and a delivery time you accept)`;
}
const shippingOptionsText = shipOptions.slice(0, 6).map((o) => `${o.name}: USD ${o.usd}, ${o.days} days`).join(' | ');

const costInr = costUsd * Number(s.usd_to_inr) + shippingInr + Number(s.returns_inr);
const raw = costInr / (1 - load);
const priceInr = Math.ceil((raw + 1) / 10) * 10 - 1; // next price ending in 9

// Images
let imgs = [];
const pi = p.productImage;
if (Array.isArray(pi)) imgs = pi;
else if (typeof pi === 'string') {
  try { const j = JSON.parse(pi); imgs = Array.isArray(j) ? j : [pi]; } catch (e) { imgs = [pi]; }
}
if (Array.isArray(p.productImageSet)) imgs = imgs.concat(p.productImageSet);
variants.forEach((v) => { if (v.variantImage) imgs.push(v.variantImage); });
imgs = [...new Set(imgs.map((u) => String(u).trim()).filter((u) => /^https:\/\//.test(u)))].slice(0, 6);

const origin = String(s.origin_country || '').trim();
const flags = [];
if (licensedHit) flags.push('LICENSED CHARACTER/BRAND: ' + licensedHit[0]);
if (!origin) flags.push('origin needed (not set)');
if (/^japan$/i.test(origin)) flags.push('Japan origin: confirm the supplier documents it');
if (shippingNote) flags.push(shippingNote);
else if (!shippingInr) {
  if (ship && ship.error) flags.push('CJ shipping lookup failed: type shipping_inr in Settings by hand, the price is not trustworthy');
  else flags.push(`CJ lists no shipping line to ${s.ship_to || 'IN'}, or shipping_inr is not set: price is not trustworthy`);
}
if (!imgs.length) flags.push('no usable images');
if (variants.length > 1) flags.push(`${variants.length} variants: price uses the dearest; set up variations by hand`);

const categories = [{ id: typeId }];
const originId = ORIGIN_IDS[origin.toLowerCase()];
if (originId) categories.push({ id: originId });
else if (origin) flags.push(`origin "${origin}" has no category: add one`);

return { json: {
  pid, flags, blocked: !!licensedHit,
  source_title: name, source_description: description,
  cost_usd: costUsd, price_inr: priceInr, variant_count: variants.length,
  origin, japanese_inspired: !!s.japanese_inspired,
  categories, tags: s.japanese_inspired ? [{ id: JAPANESE_INSPIRED_TAG_ID }] : [],
  images: imgs.map((src) => ({ src })),
  weight_g: num(p.productWeight),
  shipping_inr: shippingInr, shipping_options_text: shippingOptionsText
} };

