const d = $input.item.json;
const prompt = `You write product pages for wabisabivibes, a calm, honest lifestyle store. Rewrite this supplier listing.

Source title: ${d.source_title}
Source description: ${d.source_description}
Country of origin (verified by the owner, may be empty): ${d.origin || 'unknown'}
Japanese-inspired design only, not made in Japan: ${d.japanese_inspired ? 'yes' : 'no'}

Rules:
- Use ONLY facts present in the source. Do not invent materials, sizes, origin, safety, certifications, quality or durability claims.
- Never say or imply the item is Japanese, handmade, small-batch, premium, authentic or limited, unless the facts above say so. If "Japanese-inspired" is yes, you may say "inspired by Japanese design".
- No supplier names, shop names, contact details, emojis, hype, countdowns or fake scarcity.
- Plain, warm, specific English. Title max 70 characters. Short description max 160 characters.
- Description: 2 short paragraphs plus a bullet list of verified details (size, material, colour, contents) only if they are in the source.
- If the source is too thin to describe honestly, say so in warnings.

Return ONLY a JSON object: {"title": string, "short_description": string, "description_html": string, "warnings": string[]}`;
return { json: { ...d, request: { model: 'claude-sonnet-5-5', max_tokens: 1200, messages: [{ role: 'user', content: prompt }] } } };

const d = $('Build Claude Request').item.json;
const res = $input.item.json || {};
const text = (res.content && res.content[0] && res.content[0].text) || '';
let out;
try { out = JSON.parse(text); }
catch (e) {
  const m = text.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('Claude did not return JSON for CJ product ' + d.pid + ': ' + text.slice(0, 200));
  out = JSON.parse(m[0]);
}
const title = String(out.title || '').trim().slice(0, 80);
if (!title) throw new Error('Claude returned an empty title for CJ product ' + d.pid);
const flags = d.flags.concat((out.warnings || []).map((w) => 'Claude: ' + w));
const body = {
  name: title,
  type: 'simple',
  status: 'draft',
  regular_price: String(d.price_inr),
  short_description: String(out.short_description || '').slice(0, 200),
  description: String(out.description_html || ''),
  categories: d.categories,
  tags: d.tags,
  images: d.images,
  manage_stock: false,
  meta_data: [
    { key: '_cj_pid', value: d.pid },
    { key: '_cj_cost_usd', value: String(d.cost_usd) },
    { key: '_cj_weight_g', value: String(d.weight_g) },
    { key: '_cj_shipping_options', value: String(d.shipping_options_text || '') },
    { key: '_review_flags', value: flags.join(' | ') }
  ]
};
if (d.origin) body.attributes = [{ name: 'Country of origin', visible: true, variation: false, options: [d.origin] }];
return { json: { body, flags, pid: d.pid, title, price_inr: d.price_inr, cost_usd: d.cost_usd } };

